const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>new Intl.NumberFormat('en-CA',{maximumFractionDigits:4}).format(v);
export function formatInputValue(value,c){if(typeof value==='boolean')return value?'On':'Off';if(typeof value==='number')return c.percentage?num(value*100)+'%':num(value)+(c.unit?' '+c.unit:'');return typeof value==='object'?JSON.stringify(value):String(value??'—');}
export function changeDescription(c){const a=c.before,b=c.after;if(a===b)return 'Unchanged';if(typeof a!=='number'||typeof b!=='number')return 'Updated';const d=b-a,sign=d>0?'+':'';const relative=a!==0?` (${sign}${num(d/Math.abs(a)*100)}% relative)` :'';return c.percentage?`${sign}${num(d*100)} percentage points${relative}`:`${sign}${num(d)}${c.unit?' '+c.unit:''}${relative}`;}
export function editProposalInput(p,index,raw){const next=structuredClone(p),c=next.changes[index];if(!c)throw Error('Input no longer exists. Recheck the summary.');let value;
 if(c.valueType==='boolean')value=raw==='true';else if(typeof c.input==='object')value=JSON.parse(raw);else if(c.valueType==='number'||c.valueType==='integer'){const text=String(raw).trim();if(c.scope==='episode'&&/^[*+-]\s*\d/.test(text))value=text.replace(/\s/g,'');else{if(!text||!Number.isFinite(Number(text)))throw Error('Enter a number.');value=Number(text)/(c.percentage?100:1);}}else value=raw;
 if(typeof value==='number'){if(c.valueType==='integer'&&!Number.isInteger(value))throw Error((c.title||c.path)+' needs a whole number.');if(c.minimum!=null&&value<c.minimum)throw Error((c.title||c.path)+' must be at least '+formatInputValue(c.minimum,c)+'.');if(c.maximum!=null&&value>c.maximum)throw Error((c.title||c.path)+' must be at most '+formatInputValue(c.maximum,c)+'.');}
 let target=c.scope==='episode'?next.episodes[c.episodeIndex].settings:next[c.scope==='town'?'townOverrides':c.scope==='operations'?'operations':'settings'];
 const keys=c.path.split('.');for(const k of keys.slice(0,-1))target=target[k]||=( {} );target[keys.at(-1)]=value;c.input=value;
 next.summary='Updated configuration — review the inputs and their effects below.';return next;
}
function control(c,index,disabled){const attrs=`data-summary-change="${index}" aria-label="${esc(c.title||c.path)}${c.percentage?' (%)':''}${c.period?' · '+esc(c.period):''}" ${disabled?'disabled':''}`;
 if(c.valueType==='boolean'||c.choices?.length){const values=c.valueType==='boolean'?[true,false]:c.choices;return `<select ${attrs}>${values.map(v=>`<option value="${esc(v)}" ${v===c.input?'selected':''}>${esc(c.valueType==='boolean'?(v?'On':'Off'):v)}</option>`).join('')}</select>`;}
 const value=typeof c.input==='object'?JSON.stringify(c.input):c.percentage&&typeof c.input==='number'?num(c.input*100).replace(/,/g,''):c.input;
 return `<input type="text" ${attrs} value="${esc(value)}" autocomplete="off">`;}
export function summaryNeedsRefresh(p){return !!p&&(!Array.isArray(p.changes)||p.changes.some(c=>!c.scope||!c.valueType));}
export function summaryMarkup(p,{disabled=false,dirty=false}={}){const legacy=summaryNeedsRefresh(p),rows=legacy?[]:p.changes||[];dirty=dirty||legacy;return `<section class="input-summary" aria-label="Input changes and effects"><h3>What your inputs change</h3><p class="field-note">These are configuration changes and model relationships, not measured result changes. Percentages distinguish relative increases from percentage points.</p>${rows.length?rows.map((c,i)=>{const varying=[c.beforeRange,c.afterRange].some(r=>r?.length===2&&r[0]!==r[1]);return `<article class="input-change"><div class="input-change-heading"><strong>${esc(c.title||c.path)}</strong><span>${esc(c.scope==='episode'?'Dated Year change':c.scope==='town'?'Town configuration':c.scope==='operations'?'Map operations':'Year baseline')}</span></div>${c.period?`<p class="input-period">${esc(c.period)}</p>`:''}<p class="input-values">${esc(formatInputValue(c.before,c))} → ${esc(formatInputValue(c.after,c))}</p><p class="input-delta">${esc(changeDescription(c))}</p>${varying?`<p class="field-note">Values vary across this period (ramps or overlaps). Before range: ${esc(c.beforeRange.map(v=>formatInputValue(v,c)).join(' – '))}; after range: ${esc(c.afterRange.map(v=>formatInputValue(v,c)).join(' – '))}. The main values compare the start before this period with the end after it.</p>`:''}<p class="input-impact">${esc(c.impact)}</p><label>Edit ${esc(c.title||c.path)}${c.percentage?' (%)':''}${control(c,i,disabled)}</label><p class="field-note">${c.scope==='episode'?'Enter a value, or *0.5 / +2 / -1 relative to the value in force. ':''}${c.percentage?'Numeric values are percentages. ':''}${c.minimum!=null?`Minimum ${esc(formatInputValue(c.minimum,c))}. `:''}${c.maximum!=null?`Maximum ${esc(formatInputValue(c.maximum,c))}.`:''}</p></article>`;}).join(''):`<p class="field-note">${legacy?'Refresh the summary to see each input’s values and effects.':'No explicit input overrides; this setup uses the prepared defaults.'}</p>`}<p class="summary-status" role="status">${dirty?'Edits need checking. Recheck to update the values and effects before applying.':''}</p><button type="button" class="secondary" data-summary-recheck ${dirty?'':'hidden'} ${disabled?'disabled':''}>Recheck summary</button>${p.episodes?.length?'<p class="field-note">Periods are compared with existing and previously listed periods. Later overlapping periods can override earlier ones.</p>':''}</section>`;}
export function collectEditedProposal(p,root){let next=p;for(const input of root.querySelectorAll('[data-summary-change]'))next=editProposalInput(next,Number(input.dataset.summaryChange),input.value);return next;}
